import numpy as np
from scipy.optimize import least_squares
def mk(extra):
    def res(p):
        d,k,q=p
        cols=[np.ones_like(T),T,T**2,1/T,eps*np.exp(-d*eps)/T]
        if extra=='kq': cols.append(np.exp(-k*T**q))
        if extra=='kq_einst': cols.append(1/(np.exp(k*T**q)-1))
        if extra=='kq_pow': cols.append(T**q)
        B=np.column_stack(cols)
        c,*_=np.linalg.lstsq(B,sigma,rcond=None)
        return sigma-B@c
    return res
for ex in ['kq','kq_einst','kq_pow']:
    best=None
